import { Button } from "@/registry/erbium/ui/button";
import { HoverCard, HoverCardContent, HoverCardTrigger } from "@/registry/erbium/ui/hover-card";

export default function HoverCardDemo() {
  return (
    <HoverCard>
      <HoverCardTrigger delay={10} closeDelay={100} render={<Button variant="link" />}>
        Hover Here
      </HoverCardTrigger>
      <HoverCardContent className="flex w-64 flex-col gap-0.5">
        <div className="font-semibold">@erbium</div>
        <div>Accessible components for building your next interface.</div>
        <div className="mt-1 text-xs text-muted-foreground">Joined December 2021</div>
      </HoverCardContent>
    </HoverCard>
  );
}

import HoverCardDemo from "../examples/upstream/hover-card-demo";

const Example = () => <HoverCardDemo />;

export default Example;
